        var greetingMatch = text.match(/(?:^|\n)\s*开场白\s*[:：]\s*([\s\S]+)$/);

        var chapter = chapterMatch ? chapterMatch[1].trim() : "";
        for (var i = 0; i < OPENING_CHAPTERS.length; i++) {
          if (chapter.includes(OPENING_CHAPTERS[i]) && OPENING_CHAPTERS[i] !== "待选择") {
