          y += 22; badge("STATUS", y); y += 78;
          rows.forEach(function (row, index) {
            ctx.font = 'bold 24px "Microsoft YaHei", sans-serif'; ctx.fillStyle = "#8b1e1e"; ctx.fillText(row[0], 70, y);
            ctx.font = bodyFont; ctx.fillStyle = "#38281d";
