nts:none;letter-spacing:1px}\n.mono-sector-no{fill:var(--sector-ink);opacity:.6;font:9px Consolas,monospace;text-anchor:middle;pointer-events:none}\n.mono-sector:is(:hover,:focus-visible){--sector-ink:#080808;--sector-bg:#fff}\n.mono-sector:is(:hover,:focus-visible) .mono-sector-shape{stroke:#080808;stroke-width:2.8}\n.mono-sector:active .mono-sector-shape{fill:#cfcfcf}\n.mono-core{position:absolute;left:50%;top:50%;transform:translate(-50%,-50%);width:94px;height:94px;padding:4px;display:flex;flex-direction:column;gap:2px;align-items:center;justify-content:center;z-index:2;background:#080808;color:#fff;border:12px solid transparent;border-image:url(\"data:image/svg+xml;base64,\") 16 stretch;font-family:\"Noto Serif CJK SC\",\"Songti SC\",\"SimSun\",serif;cursor:pointer;box-sizing:border-box;line-height:1.15}\n.mono-core span{font-size:15px;letter-spacing:2px;white-space:nowrap}\n.mono-aperture{width:34px;height:34px;flex:none;display:block}\n.mono-core:is(:hover,:focus-visible){filter:invert(1);outline:1px solid #fff;outline-offset:1px}\n.mono-wheel-caption{position:absolute;top:80%;left:30%;width:40%;text-align:center;line-height:1.65;color:#111;font-family:\"Noto Serif CJK SC\",\"Songti SC\",\"SimSun\",serif;pointer-events:none}\n.mono-wheel-caption b{display:block;font-size:13px;font-weight:700;letter-spacing:.5px}\n.mono-wheel-caption small{display:block;font:9px/1.6 Consolas,monospace;letter-spacing:1px}\n\n.mono-launcher .mono-core{width:26%;height:26%}.mono-launcher .mono-core .mono-aperture{width:32px;height:32px}@media(max-width:335px){.mono-launcher .mono-core .mono-aperture{width:24px;height:24px}.mono-launcher .mono-core span{font-size:12px}}\n\n.ti-shield-check{--ph-icon:url(\"data:image/svg+xml;base64,\")}\n.ti-messages{--ph-icon:url(\"data:image/svg+xml;base64,\")}\n.ti-sparkles{--ph-icon:url(\"data:image/svg+xml;base64,\")}\n.ti-news{--ph-icon:url(\"data:image/svg+xml;base64,\")}\n.ti-radar-2{--ph-icon:url(\"data:image/svg+xml;base64,\")}\n.ti-photo{--ph-icon:url(\"data:image/svg+xml;base64,\")}\n.ti-world{--ph-icon:url(\"data:image/svg+xml;base64,\")}\n.ti-settings{--ph-icon:url(\"data:image/svg+xml;base64,\")}\n.ti-home{--ph-icon:url(\"data:image/svg+xml;base64,\")}\n.ti-sword{--ph-icon:url(\"data:image/svg+xml;base64,\")}\n.ti-shield{--ph-icon:url(\"data:image/svg+xml;base64,\")}\n.ti-bolt{--ph-icon:url(\"data:image/svg+xml;base64,\")}\n.ti-map-pin{--ph-icon:url(\"data:image/svg+xml;base64,\")}\n.ti-clock{--ph-icon:url(\"data:image/svg+xml;base64,\")}\n.ti-trophy{--ph-icon:url(\"data:image/svg+xml;base64,\")}\n.ti-battery-3{--ph-icon:url(\"data:image/svg+xml;base64,\")}\n\u003c/style>\n\u003cstyle>\n/* Color-block status module. Kept inside the dossier; shell and wheel keep their theme. */\n#blazer-body.gba-status {\n  --gba-ink: #1b2748;\n  --gba-navy: #2b4773;\n  --gba-navy-light: #3d608b;\n  --gba-paper: #fff3d6;\n  --gba-paper-shade: #e9dcb9;\n  --gba-muted: #526076;\n  --gba-gold: #efbd4f;\n  --gba-teal: #319e8e;\n  --gba-teal-light: #82d1ad;\n  --gba-red: #c85b46;\n  --ink: var(--gba-ink);\n  --ink2: #35425b;\n  --muted: var(--gba-muted);\n  --card: var(--gba-paper);\n  --card2: var(--gba-paper-shade);\n  --hair: #82908f;\n  --sky: #205f79;\n  --crimson: var(--gba-red);\n  --press: var(--gba-paper-shade);\n  color: var(--gba-ink);\n  background: #223759;\n  padding: 2px 0 16px;\n  font-size: 13px;\n  line-height: 1.65;\n  overflow-wrap: anywhere;\n  scrollbar-color: var(--gba-gold) var(--gba-ink);\n  color-scheme: light;\n}\n\n#blazer-body.gba-status *,\n#blazer-body.gba-status *::before,\n#blazer-body.gba-status *::after {\n  box-sizing: border-box;\n}\n\n#blazer-body.gba-status .card1 {\n  margin: 12px 10px;\n  padding: 12px;\n  border: 2px solid var(--gba-ink);\n  border-radius: 0;\n  background: var(--gba-paper);\n  color: var(--gba-ink);\n  box-shadow: 2px 2px 0 #14203a;\n  min-width: 0;\n}\n\n#blazer-body.gba-status .ct {\n  background: var(--gba-navy);\n  color: var(--gba-paper);\n  border-bottom: 2px solid var(--gba-gold);\n  padding: 6px 9px;\n  margin: 12px 0 9px;\n  font-family: var(--font-ui);\n  font-size: 12px;\n  font-weight: 700;\n  line-height: 1.5;\n  letter-spacing: .5px;\n}\n\n#blazer-body.gba-status .card1 > .ct:first-child {\n  margin: -12px -12px 12px;\n}\n\n#blazer-body.gba-status .card-avatar {\n  background: var(--gba-gold);\n  color: var(--gba-ink);\n  border: 2px solid var(--gba-ink);\n  box-shadow: none;\n}\n\n#blazer-body.gba-status .card-rank-badge {\n  display: inline-block;\n  vertical-align: middle;\n  min-width: 27px;\n  margin-left: 3px;\n  padding: 2px 5px;\n  border: 2px solid var(--gba-ink);\n  border-radius: 0;\n  background: var(--gba-gold);\n  color: var(--gba-ink);\n  font: 700 13px/1.3 var(--font-num);\n  text-align: center;\n  text-shadow: none;\n  white-space: nowrap;\n}\n\n/* A navy field keeps the chart distinct from the paper explanation beneath it. */\n#blazer-body.gba-status .radar-container {\n  background: var(--gba-navy);\n  border: 2px solid var(--gba-ink);\n  padding: 12px 0;\n  min-width: 0;\n}\n\n#blazer-body.gba-status .radar-svg {\n  display: block;\n  width: min(100%, 320px);\n  max-height: none;\n  height: auto;\n  overflow: visible;\n}\n\n#blazer-body.gba-status .radar-web,\n#blazer-body.gba-status .radar-web-spoke,\n#blazer-body.gba-status .radar-spoke {\n  stroke: #91abc0;\n  stroke-width: 1;\n  stroke-opacity: .7;\n}\n\n#blazer-body.gba-status .radar-web { fill: none; }\n\n#blazer-body.gba-status .radar-polygon {\n  fill: var(--gba-teal);\n  fill-opacity: .72;\n  stroke: var(--gba-gold);\n  stroke-width: 2.2;\n  filter: none;\n}\n\n#blazer-body.gba-status .radar-point {\n  fill: var(--gba-paper);\n  stroke: var(--gba-ink);\n  stroke-width: 2;\n}\n\n#blazer-body.gba-status .radar-label {\n  fill: var(--gba-paper);\n  font-family: var(--font-ui);\n  font-size: 10px;\n  font-weight: 600;\n}\n\n#blazer-body.gba-status .radar-rank-badge {\n  fill: var(--gba-gold);\n  font: 700 12px var(--font-num);\n}\n\n#blazer-body.gba-status .radar-legend,\n#blazer-body.gba-status .gba-note {\n  color: var(--gba-muted);\n  font-size: 12px;\n  line-height: 1.65;\n  margin: 9px 0 0;\n}\n\n#blazer-body.gba-status .noble-art-block {\n  margin-top: 10px;\n  padding: 9px 10px;\n  border: 1px solid #a1a58f;\n  border-left: 4px solid var(--gba-teal);\n  border-radius: 0;\n  background: var(--gba-paper-shade);\n}\n\n#blazer-body.gba-status .noble-art-title {\n  color: var(--gba-ink);\n  font: 700 13px/1.6 var(--font-ui);\n  flex-wrap: wrap;\n}\n\n#blazer-body.gba-status .noble-art-desc {\n  color: var(--ink2);\n  font-size: 12px;\n  line-height: 1.7;\n}\n\n/* Native details provides one full-width, keyboard-operable contact control. */\n#blazer-body.gba-status .roster-list {\n  padding: 10px;\n  gap: 12px;\n}\n\n#blazer-body.gba-status details.roster-card {\n  display: block;\n  padding: 0;\n  margin: 0;\n  border: 2px solid var(--gba-ink);\n  border-radius: 0;\n  background: var(--gba-paper);\n  color: var(--gba-ink);\n  box-shadow: 2px 2px 0 #14203a;\n  cursor: auto;\n  min-width: 0;\n}\n\n#blazer-body.gba-status .gba-contact-summary {\n  display: flex;\n  align-items: center;\n  gap: 10px;\n  padding: 11px 10px;\n  min-height: 68px;\n  background: var(--gba-navy);\n  color: var(--gba-paper);\n  list-style: none;\n  cursor: pointer;\n  touch-action: manipulation;\n}\n\n#blazer-body.gba-status .gba-contact-summary::-webkit-details-marker { display: none; }\n#blazer-body.gba-status .gba-contact-summary::marker { content: ''; }\n\n#blazer-body.gba-status .gba-contact-summary:hover {\n  background: var(--gba-navy-light);\n}\n\n#blazer-body.gba-status .gba-contact-summary:focus-visible {\n  outline: 3px solid var(--gba-gold);\n  outline-offset: -3px;\n}\n\n#blazer-body.gba-status .gba-contact[open] > .gba-contact-summary {\n  border-bottom: 3px solid var(--gba-gold);\n}\n\n#blazer-body.gba-status .roster-ava {\n  width: 42px;\n  height: 44px;\n  flex: 0 0 42px;\n  border: 2px solid var(--gba-ink);\n  border-radius: 0;\n  background: var(--gba-gold);\n  color: var(--gba-ink);\n  font: 700 24px/1 var(--font-title);\n  box-shadow: none;\n}\n\n#blazer-body.gba-status .roster-info {\n  flex: 1 1 auto;\n  min-width: 0;\n  overflow-wrap: anywhere;\n}\n\n#blazer-body.gba-status .roster-name {\n  color: inherit;\n  font-size: 14px;\n  font-weight: 700;\n  line-height: 1.7;\n}\n\n#blazer-body.gba-status .roster-device {\n  color: var(--ink2);\n  font-size: 12px;\n  line-height: 1.7;\n  white-space: normal;\n  overflow-wrap: anywhere;\n}\n\n#blazer-body.gba-status .gba-contact-summary .roster-device {\n  color: #dae6e5;\n  margin-top: 3px;\n}\n\n#blazer-body.gba-status .gba-disclosure {\n  flex: 0 0 auto;\n  color: var(--gba-gold);\n  font: 700 12px/1.5 var(--font-ui);\n  text-align: center;\n}\n\n#blazer-body.gba-status .gba-disclosure::before {\n  content: '▸';\n  display: block;\n  font-size: 17px;\n  line-height: 1;\n}\n\n#blazer-body.gba-status .gba-contact[open] .gba-disclosure::before { content: '▾'; }\n\n#blazer-body.gba-status .gba-contact-body {\n  padding: 12px;\n  color: var(--gba-ink);\n  background: var(--gba-paper);\n  min-width: 0;\n}\n\n#blazer-body.gba-status .gba-contact-body > .roster-device + .roster-device {\n  margin-top: 6px;\n}\n\n#blazer-body.gba-status .gba-contact-body dl {\n  display: grid;\n  grid-template-columns: max-content minmax(0, 1fr);\n  gap: 7px 10px;\n  margin: 0;\n}\n\n#blazer-body.gba-status .gba-contact-body dt { color: var(--gba-muted); }\n#blazer-body.gba-status .gba-contact-body dd { margin: 0; min-width: 0; }\n\n/* Solid meters have a single light edge; neither value is indicated by color alone. */\n#blazer-body.gba-status .gba-bond-panel {\n  margin-top: 12px;\n  padding-top: 12px;\n  border-top: 2px solid #bcc1a7;\n}\n\n#blazer-body.gba-status .gba-metric {\n  display: flex;\n  flex-wrap: wrap;\n  align-items: baseline;\n  justify-content: space-between;\n  gap: 4px 10px;\n  color: var(--gba-ink);\n  font-size: 12px;\n  margin: 9px 0 5px;\n}\n\n#blazer-body.gba-status .gba-metric strong,\n#blazer-body.gba-status .gba-metric b {\n  font: 700 15px/1.4 var(--font-num);\n  color: var(--gba-ink);\n}\n\n#blazer-body.gba-status .gba-meter {\n  height: 16px;\n  width: 100%;\n  border: 2px solid var(--gba-ink);\n  background: #c6c9b2;\n  overflow: hidden;\n}\n\n#blazer-body.gba-status .gba-meter > span {\n  display: block;\n  height: 100%;\n  min-width: 0;\n  max-width: 100%;\n  background: var(--gba-teal);\n  border-top: 3px solid var(--gba-teal-light);\n}\n\n#blazer-body.gba-status .gba-meter[data-kind='support'] > span {\n  background: #d59635;\n  border-top-color: #ffde83;\n}\n\n#blazer-body.gba-status .gba-support-track {\n  display: flex;\n  gap: 5px;\n  margin: 9px 0 0;\n  padding: 0;\n  list-style: none;\n}\n\n#blazer-body.gba-status .gba-support-track li {\n  flex: 1 1 0;\n  min-width: 0;\n  padding: 5px 2px;\n  border: 1px solid #8c967f;\n  background: var(--gba-paper-shade);\n  color: #53616c;\n  font: 700 13px/1.5 var(--font-num);\n  text-align: center;\n}\n\n#blazer-body.gba-status .gba-support-track li[data-achieved='true'] {\n  border-color: var(--gba-ink);\n  border-bottom: 3px solid var(--gba-gold);\n  padding-bottom: 3px;\n  background: var(--gba-navy);\n  color: var(--gba-paper);\n}\n\n#blazer-body.gba-status .gba-support-track small {\n  display: block;\n  font: 11px/1.4 var(--font-num);\n}\n\n#blazer-body.gba-status .gba-unknown {\n  color: var(--gba-muted);\n  font-size: 12px;\n  font-style: normal;\n}\n\n#blazer-body.gba-status .gba-romance-panel {\n  border-top: 2px solid var(--gba-red);\n  margin-top: 14px;\n  padding-top: 5px;\n}\n\n#blazer-body.gba-status .gba-romance-track {\n  display: grid;\n  grid-template-columns: repeat(2, minmax(0, 1fr));\n  gap: 6px;\n}\n\n#blazer-body.gba-status .gba-romance-track li {\n  display: flex;\n  justify-content: space-between;\n  align-items: center;\n  gap: 5px;\n  padding: 5px 7px;\n  font-family: var(--font-ui);\n  